using System;using System.Linq;using System.Globalization;using System.Collections.Generic;using System.Windows;using System.Windows.Media;using System.Windows.Input;
class ArchiveSeries {public string Label,Color;public double?[] Values;}
class ArchivePlot:FrameworkElement {
 public DateTime[] Dates=new DateTime[0];public ArchiveSeries[] Series=new ArchiveSeries[0];public bool Bars=true,Lines=true;public string Unit="";public double? Maximum;public bool ShowTime;public int StepMinutes=1440;public QuotaAuditEvent[] Markers=new QuotaAuditEvent[0];int hovered=-1;double hoverY=80;
 public ArchivePlot(){Height=300;MinWidth=650;MouseMove+=(s,e)=>{var point=e.GetPosition(this);hoverY=point.Y;HoverAt(point.X);};MouseLeave+=(s,e)=>{hovered=-1;ToolTip=null;InvalidateVisual();};}
 int MarkerIndex(QuotaAuditEvent m){if(Dates.Length==0)return -1;double minutes=(m.Utc.ToLocalTime()-Dates[0]).TotalMinutes;int i=(int)Math.Floor(minutes/Math.Max(1,StepMinutes));return minutes<0||i>=Dates.Length?-1:i;}
 int MarkerSeries(QuotaAuditEvent m){string label=MonitorEngine.Label(m.Windows=="五小时"?"codex5h":"codex7d");return Array.FindIndex(Series,v=>v.Label==label);}
 double MarkerX(QuotaAuditEvent m){int i=MarkerIndex(m);if(i<0)return Double.NaN;double slot=(ActualWidth-84)/Dates.Length,center=64+slot*(i+.5);int k=MarkerSeries(m);if(!Bars||k<0)return center;double bar=Math.Max(1,Math.Min(14,slot*.75/Math.Max(1,Series.Length)));return center+(k-Series.Length/2.0)*bar+Math.Max(1,bar-1)/2;}
 internal void HoverAt(double x){hovered=ChartHover.Index(x,64,ActualWidth-84,Dates.Length);if(hovered<0){ToolTip=null;InvalidateVisual();return;}int i=hovered;string value=(ShowTime?Dates[i].ToString("yyyy-MM-dd HH:mm"):Dates[i].ToString("yyyy-MM-dd"))+String.Join("",Series.Select(a=>"\n"+a.Label+"："+(i<a.Values.Length&&a.Values[i].HasValue?a.Values[i].Value.ToString("N1")+" "+Unit:"无记录")));foreach(var marker in Markers.Where(m=>m.Utc!=default(DateTime))){double px=MarkerX(marker);if(Math.Abs(px-x)<=8)value+="\n◆ "+QuotaAudit.Describe(marker);}ToolTip=value;InvalidateVisual();}
 static void Text(DrawingContext dc,string t,double x,double y,Brush brush,double dpi){dc.DrawText(new FormattedText(t,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),11,brush,dpi),new Point(x,y));}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);ChartHover.Background(dc,ActualWidth,ActualHeight);if(ActualWidth<100||Dates.Length==0)return;double dpi=VisualTreeHelper.GetDpi(this).PixelsPerDip,slot=(ActualWidth-84)/Dates.Length,top=18,height=200;var muted=TryFindResource("DeskMuted") as Brush??Brushes.SlateGray;var grid=TryFindResource("DeskLine") as Brush??Brushes.Gray;double max=Maximum??Math.Max(1,Series.SelectMany(s=>s.Values).Where(v=>v.HasValue).Select(v=>v.Value).DefaultIfEmpty(1).Max()*1.1);for(int j=0;j<=4;j++){double y=top+height*j/4;dc.DrawLine(new Pen(grid,.6),new Point(62,y),new Point(ActualWidth-15,y));Text(dc,(max*(4-j)/4).ToString(max>10000?"0,,.##M":"0.#"),2,y-7,muted,dpi);}for(int i=0;i<Dates.Length;i++){double center=64+slot*(i+.5);if(i%Math.Max(1,(int)Math.Ceiling((ShowTime&&Dates.Length>288?80:48)/slot))==0)Text(dc,(ShowTime?Dates[i].ToString(Dates.Length<=288?"HH:mm":"MM/dd HH:mm"):Dates[i].ToString("MM/dd")),center-16,228,muted,dpi);if(!Series.Any(s=>s.Values[i].HasValue))Text(dc,"—",center-3,top+height-20,muted,dpi);for(int k=0;k<Series.Length;k++){var series=Series[k];if(!series.Values[i].HasValue)continue;var brush=new SolidColorBrush((Color)ColorConverter.ConvertFromString(series.Color));double y=top+height-Math.Max(0,series.Values[i].Value)/max*height;double bar=Math.Max(1,Math.Min(14,slot*.75/Math.Max(1,Series.Length)));double pointX=Bars?center+(k-Series.Length/2.0)*bar+Math.Max(1,bar-1)/2:center;if(Bars){dc.PushOpacity(Lines?.46:.85);dc.DrawRoundedRectangle(brush,null,new Rect(center+(k-Series.Length/2.0)*bar,y,Math.Max(1,bar-1),Math.Max(1,top+height-y)),2,2);dc.Pop();}if(Lines){if(i>0&&series.Values[i-1].HasValue){double before=top+height-Math.Max(0,series.Values[i-1].Value)/max*height;dc.DrawLine(new Pen(brush,2),new Point(pointX-slot,before),new Point(pointX,y));}dc.DrawEllipse(brush,null,new Point(pointX,y),2.5,2.5);}}}foreach(var marker in Markers.Where(m=>m.Kind=="reset-observed"&&m.Utc!=default(DateTime))){double x=MarkerX(marker);if(Double.IsNaN(x)||x<64||x>ActualWidth-20)continue;int index=MarkerIndex(marker),seriesIndex=MarkerSeries(marker);double markY=top+9;if(seriesIndex>=0&&index<Series[seriesIndex].Values.Length&&Series[seriesIndex].Values[index].HasValue)markY=top+height-Math.Max(0,Series[seriesIndex].Values[index].Value)/max*height;ChartHover.ResetMark(dc,x,markY);}if(hovered>=0&&hovered<Dates.Length)ChartHover.Show(dc,this,64+slot*(hovered+.5),hoverY,64,ActualWidth-20,top,top+height,ToolTip as string);for(int k=0;k<Series.Length;k++)Text(dc,Series[k].Label,64+k*145,265,new SolidColorBrush((Color)ColorConverter.ConvertFromString(Series[k].Color)),dpi);if(!Bars&&!Lines)Text(dc,"请打开柱状图或折线图图层",80,100,muted,dpi);}
}
class ArchiveSlice {public string Label,Color;public double Value;}
class ArchiveDonut:FrameworkElement {
 public ArchiveSlice[] Slices=new ArchiveSlice[0];public string Caption="",Unit="";public ArchiveDonut(){Height=210;MinWidth=280;MouseMove+=(s,e)=>HoverAt(e.GetPosition(this));MouseLeave+=(s,e)=>ToolTip=null;}
 internal void HoverAt(Point point){double dx=point.X-88,dy=point.Y-97,r=Math.Sqrt(dx*dx+dy*dy),total=Slices.Sum(x=>Math.Max(0,x.Value));if(r<45||r>71||total<=0){ToolTip=null;return;}double angle=Math.Atan2(dy,dx)+Math.PI/2;if(angle<0)angle+=Math.PI*2;double cursor=angle/(Math.PI*2),sum=0;foreach(var slice in Slices){sum+=Math.Max(0,slice.Value)/total;if(cursor<=sum){ToolTip=slice.Label+"："+slice.Value.ToString("N1")+" "+Unit+" · "+(100*slice.Value/total).ToString("F1")+"%";return;}}ToolTip=null;}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);double total=Slices.Sum(s=>Math.Max(0,s.Value)),dpi=VisualTreeHelper.GetDpi(this).PixelsPerDip;Brush ink=TryFindResource("DeskMuted") as Brush??Brushes.SlateGray;var center=new Point(88,97);dc.DrawEllipse(null,new Pen(ink,21),center,58,58);double angle=-Math.PI/2;for(int i=0;i<Slices.Length;i++){var slice=Slices[i];double portion=total>0?Math.Max(0,slice.Value)/total:0;var brush=new SolidColorBrush((Color)ColorConverter.ConvertFromString(slice.Color));if(portion>0){var pen=new Pen(brush,22);if(portion>.999999)dc.DrawEllipse(null,pen,center,58,58);else{var arc=new StreamGeometry();using(var context=arc.Open()){context.BeginFigure(new Point(center.X+58*Math.Cos(angle),center.Y+58*Math.Sin(angle)),false,false);double end=angle+portion*Math.PI*2;context.ArcTo(new Point(center.X+58*Math.Cos(end),center.Y+58*Math.Sin(end)),new Size(58,58),0,portion>.5,SweepDirection.Clockwise,true,false);}dc.DrawGeometry(null,pen,arc);}angle+=portion*Math.PI*2;}dc.DrawText(new FormattedText(slice.Label+"  "+(total>0?(portion*100).ToString("F1")+"%":"无记录"),CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),12,brush,dpi),new Point(180,40+i*28));}dc.DrawText(new FormattedText(total>0?Caption:"暂无记录",CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),11,ink,dpi),new Point(48,91));}
}
